/* Only the intercepted CUDA Driver API symbols are exported: the library must
   offer exactly these names, or a symbol declared without extern "C" becomes
   part of our ABI. */

{
    global:
        cuInit;
        cuDriverGetVersion;
        cuDeviceGetCount;
        cuDeviceGet;
        cuDeviceGetName;
        cuDeviceGetAttribute;
        cuDeviceTotalMem;
        cuDevicePrimaryCtxRetain;
        cuDevicePrimaryCtxRelease;
        cuCtxCreate;
        cuCtxDestroy;
        cuCtxSetCurrent;
        cuCtxGetCurrent;
        cuCtxGetDevice;
        cuCtxGetApiVersion;
        cuCtxSynchronize;
        cuMemAlloc;
        cuMemAlloc_v2;
        cuMemFree;
        cuMemFree_v2;
        cuMemHostAlloc;
        cuMemHostAlloc_v2;
        cuMemFreeHost;
        cuMemHostRegister;
        cuMemHostUnregister;
        cuMemGetInfo;
        cuStreamCreate;
        cuStreamCreateWithPriority;
        cuStreamDestroy;
        cuStreamSynchronize;
        cuStreamQuery;
        cuStreamWaitEvent;
        cuEventCreate;
        cuEventDestroy;
        cuEventRecord;
        cuEventSynchronize;
        cuEventQuery;
        cuEventElapsedTime;
        cuModuleLoadData;
        cuModuleLoadDataEx;
        cuModuleUnload;
        cuModuleGetFunction;
        cuFuncSetAttribute;
        cuFuncGetAttribute;
        cuLaunchKernel;
    cuascendLastError;
        cuMemcpy;
        cuMemcpyHtoD;
        cuMemcpyDtoH;
        cuMemcpyDtoD;
        cuMemcpyHtoH;
        cuMemcpyAsync;
        cuMemcpy2D;
        cuMemcpy2DUnaligned;
        cuMemsetD8;
        cuMemsetD16;
        cuMemsetD32;
        cuMemcpyHtoDAsync;
        cuMemcpyDtoDAsync;
        cuCtxGetFlags;
        cuCtxSetFlags;
        cuStreamGetFlags;
        cuDeviceGetUuid;
        cuOccupancyMaxActiveBlocksPerMultiprocessor;
        cuFuncSetCacheConfig;
        cuFuncSetSharedMemConfig;
        cuLaunchHostFunc;
        cuDeviceGetDefaultMemPool;
        cuDeviceSetMemPool;
        cuMemPoolGetAttribute;
        cuMemPoolSetAttribute;
        cuMemPoolTrimTo;
        cuGetErrorString;
        cuGetErrorName;
        cuGetLastError;
    local:
        *;
};
